"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[23600],{3331:(e,r,t)=>{t.d(r,{R:()=>o,x:()=>a});var i=t(36672);const n={},s=i.createContext(n);function o(e){const r=i.useContext(s);return i.useMemo((function(){return"function"==typeof e?e(r):{...r,...e}}),[r,e])}function a(e){let r;return r=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:o(e.components),i.createElement(s.Provider,{value:r},e.children)}},64242:(e,r,t)=>{t.r(r),t.d(r,{assets:()=>l,contentTitle:()=>a,default:()=>m,frontMatter:()=>o,metadata:()=>i,toc:()=>d});const i=JSON.parse('{"id":"2023/04/17","title":"2023-04-17","description":"Afstresning Booking.com","source":"@site/i18n/da/docusaurus-plugin-content-docs/current/2023/04/17.md","sourceDirName":"2023/04","slug":"/2023/04/17","permalink":"/da/2023/04/17","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/da/docusaurus-plugin-content-docs//current/2023/04/17.md","tags":[],"version":"current","frontMatter":{"localized_date":"17. april 2023","top_news":"Afstresning Booking.com"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-18","permalink":"/da/2023/04/18"},"next":{"title":"2023-04-16","permalink":"/da/2023/04/16"}}');var n=t(23420),s=t(3331);const o={localized_date:"17. april 2023",top_news:"Afstresning Booking.com"},a="2023-04-17",l={},d=[{value:"Afstresning Booking.com",id:"afstresning-bookingcom",level:2},{value:"Jeg har brugt Stable Diffusion og Dreambooth til at skabe et kunstportr\xe6t af min hund",id:"jeg-har-brugt-stable-diffusion-og-dreambooth-til-at-skabe-et-kunstportr\xe6t-af-min-hund",level:2},{value:"AT&amp;T Wireless trafikformning g\xf8r tilsyneladende nogle websteder ubrugelige",id:"att-wireless-trafikformning-g\xf8r-tilsyneladende-nogle-websteder-ubrugelige",level:2},{value:"Future Blues - Emily&#39;s Cowboy Bebop Page (1999)",id:"future-blues---emilys-cowboy-bebop-page-1999",level:2},{value:"Opvaskemaskine Laks",id:"opvaskemaskine-laks",level:2},{value:"Pico3D: Open World 3D-spilmotor til PicoSystem (RP2040-mikrocontroller)",id:"pico3d-open-world-3d-spilmotor-til-picosystem-rp2040-mikrocontroller",level:2},{value:"Wayback: Self-hosted arkiveringstjeneste integreret med Internet Archive",id:"wayback-self-hosted-arkiveringstjeneste-integreret-med-internet-archive",level:2},{value:"Det hurtigste matematiske s\xe6tningsbibliotek til nettet",id:"det-hurtigste-matematiske-s\xe6tningsbibliotek-til-nettet",level:2},{value:"&#39;Algebra for none&#39; mislykkes i San Francisco",id:"algebra-for-none-mislykkes-i-san-francisco",level:2},{value:"FSF sm\xe6kker Google over at droppe JPEG-XL i Chrome",id:"fsf-sm\xe6kker-google-over-at-droppe-jpeg-xl-i-chrome",level:2}];function g(e){const r={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,s.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(r.header,{children:(0,n.jsx)(r.h1,{id:"2023-04-17",children:"2023-04-17"})}),"\n",(0,n.jsx)(r.h2,{id:"afstresning-bookingcom",children:"Afstresning Booking.com"}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.a,{href:"https://www.alexcharlton.co/projects/booking-com-de-stresser",children:"Original"}),'.\nForfatteren deler en udtalelse om overforbruget af overtalelsestaktik p\xe5 e-handelswebsteder, is\xe6r Booking.com, og introducerer deres Chrome-udvidelse "De-stresser", som fjerner stressfremkaldende meddelelser og notifikationer fra Booking.com, hvilket giver brugerne en mere behagelig oplevelse. Ved at skjule overtalelsesm\xe6rker og justere sproget til at lyde mere positivt, giver De-stresser brugerne en mere rolig og afslappet bookingoplevelse. Udvidelsen er nu live og kan bruges p\xe5 Booking.com.']}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35590734",children:"Discussion Service"}),'.\nBooking.com er udsat for kritik for sin brug af salgstaktik med h\xf8jt pres, herunder hastebeskeder og pop-ups, der kan afskr\xe6kke brugerne. Kritikere h\xe6vder, at denne tilgang prioriterer kortsigtede m\xe5linger frem for langsigtet kundeloyalitet. Brugerne rapporterer, at de har fundet m\xe5der at omg\xe5 disse taktikker p\xe5, herunder ved hj\xe6lp af udvidelser til at blokere eller filtrere dem. I mellemtiden diskuterer Discussion Service-brugere fordelene ved A/B-testning, og nogle peger p\xe5, at det kan skabe "m\xf8rke m\xf8nstre" p\xe5 websteder. P\xe5 trods af disse bekymringer forts\xe6tter mange brugere med at bruge bookingaggregatorer som Booking.com og Expedia, enten af praktiske \xe5rsager eller fordi de tilbyder favorable priser og afbestillingsregler. Nogle eksperter advarer om, at man ved at booke direkte hos hotellerne kan f\xe5 bedre muligheder for at l\xf8se tvister, mens andre p\xe5peger, at provisionssatserne for bookingwebsteder kan variere meget afh\xe6ngigt af hotellet. Ikke desto mindre kan loyalitetsprogrammer fra hoteller give betydelige fordele for hyppigt rejsende.']}),"\n",(0,n.jsx)(r.h2,{id:"jeg-har-brugt-stable-diffusion-og-dreambooth-til-at-skabe-et-kunstportr\xe6t-af-min-hund",children:"Jeg har brugt Stable Diffusion og Dreambooth til at skabe et kunstportr\xe6t af min hund"}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.a,{href:"https://www.shruggingface.com/blog/how-i-used-stable-diffusion-and-dreambooth-to-create-a-painted-portrait-of-my-dog",children:"Original"}),".\nArtiklen omhandler brugen af Stable Diffusion og Dreambooth AI-teknikker til at skabe et malet portr\xe6t af en hund i h\xf8j kvalitet. Forfatteren deler hele deres arbejdsgang og giver detaljerede instruktioner om, hvordan man tr\xe6ner en Dreambooth-model p\xe5 fotos af deres hund. Artiklen diskuterer ogs\xe5 brugen af opskalering til at forst\xf8rre sm\xe5 billeder til udskrifter af h\xf8j kvalitet og introducerer Stable Diffusion som en game-changer for verdenen af tekst-til-billede generativ kunst."]}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35592847",children:"Discussion Service"}),".\nEn Discussion Service-bruger brugte Stable Diffusion og Dreambooth til at skabe et kunstportr\xe6t af sin hund, mens kommentarer diskuterede modstanden mod AI-kunst og debatter om ophavsret og fair use. Brugen af generativ AI til kunst rejser etiske sp\xf8rgsm\xe5l vedr\xf8rende ophavsret og fair use, og der er delte meninger om sagen. Nogle kritiserede Stable Diffusion for at bruge ukompenserede stj\xe5lne kunstv\xe6rker som tr\xe6ningsdata, mens andre roste teknologien og dens potentiale for yderligere innovation p\xe5 omr\xe5det."]}),"\n",(0,n.jsx)(r.h2,{id:"att-wireless-trafikformning-g\xf8r-tilsyneladende-nogle-websteder-ubrugelige",children:"AT&T Wireless trafikformning g\xf8r tilsyneladende nogle websteder ubrugelige"}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.a,{href:"https://adriano.fyi/post/2023/2023-04-16-att-traffic-shaping-makes-websites-unusable/",children:"Original"}),'.\nAT&T\'s "ubegr\xe6nsede" 100Mbit abonnement med 50GB til prioriterede data kan aggressivt trafikformning, hvilket g\xf8r nogle websites ubrugelige, mens en test viste, at et Verizon SIM-kort ikke havde samme problem. Akamai-trafik viser tegn p\xe5 fors\xe6tlig manipulation af TCP-str\xf8mmen. Trafikformning p\xe5virker kun data-only-konti p\xe5 erhvervskonti.']}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35592607",children:"Discussion Service"}),".\nAT&T Wireless begr\xe6nser angiveligt IP-adresser for nogle videostreamingwebsteder, hvilket g\xf8r nogle websteder ubrugelige og for\xe5rsager uoverensstemmelser i internethastighedstests. Brugere har foresl\xe5et l\xf8sninger som f.eks. at indgive en klage til FCC, bruge en VPN til at omg\xe5 throttling eller pr\xf8ve et andet APN. Nogle kommentatorer er skeptiske over for, at der ligger ondsindede hensigter bag neddroslingen, mens andre foresl\xe5r l\xf8sninger som hastighedsgr\xe6nser eller nedjustering af videokvaliteten for at bevare datatildelingen."]}),"\n",(0,n.jsx)(r.h2,{id:"future-blues---emilys-cowboy-bebop-page-1999",children:"Future Blues - Emily's Cowboy Bebop Page (1999)"}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.a,{href:"https://futureblues.com/",children:"Original"}),".\nBeklager, der er ingen tekst, som jeg kan opsummere."]}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35589124",children:"Discussion Service"}),".\nDiscussion Service-brugerne udtrykker nostalgi over for de klassiske websteders originale og kreative design og s\xe6tter dem i kontrast til de moderne websteders standardiserede, st\xf8jende og pengeskabte karakter, hvilket tyder p\xe5 en l\xe6ngsel efter mere kunstneriske, individualitetsfokuserede medielandskaber. Der opst\xe5r diskussionspunkter, hvor Wikipedia og Fandom sammenlignes, og hvor der skelnes mellem mobile og desktop-only-websteder, og hjemmesidens design v\xe6kker b\xe5de nostalgi og forundring over dets lang levetid. Alt i alt giver indl\xe6gget et indblik i brugernes gode minder om det tidlige internet og giver en platform til at diskutere den nuv\xe6rende tilstand p\xe5 nettet."]}),"\n",(0,n.jsx)(r.h2,{id:"opvaskemaskine-laks",children:"Opvaskemaskine Laks"}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.a,{href:"https://en.wikipedia.org/wiki/Dishwasher_salmon",children:"Original"}),".\nOpvaskemaskine laks er en fiskeret, der fremstilles ved at pakke stykker af laks ind i mindst to lag aluminiumsfolie og l\xe6gge dem i opvaskemaskinen under vaske- og t\xf8rrecyklussen. Metoden blev f\xf8rste gang demonstreret i USA af Vincent Price i 1975 og er siden blevet omtalt i forskellige medier. Der er imidlertid bekymring over konsistensen af temperaturerne i opvaskemaskinerne, hvilket kan f\xf8re til ufuldst\xe6ndig tilberedning og potentielle sundhedsrisici."]}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35586683",children:"Discussion Service"}),".\nEn artikel i Hacker News om tilberedning af laks i en opvaskemaskine udl\xf8ser en debat om tilberedningsmetodens sikkerhed, hvor brugere i f\xf8devaresikkerhedsindustrien im\xf8deg\xe5r p\xe5stande fra en YouTuber's unders\xf8gelse. Mens sikkerheden ved tilberedning i opvaskemaskine afh\xe6nger af flere faktorer, kr\xe6ves der mindst 63 \xb0C i 15 sekunder for at dr\xe6be bakterier i laks."]}),"\n",(0,n.jsx)(r.h2,{id:"pico3d-open-world-3d-spilmotor-til-picosystem-rp2040-mikrocontroller",children:"Pico3D: Open World 3D-spilmotor til PicoSystem (RP2040-mikrocontroller)"}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.a,{href:"https://github.com/bernhardstrobl/Pico3D",children:"Original"}),".\nPico3D-spilmotoren bruger den anden kerne i RP2040 som en dedikeret rasterizer/GPU til at k\xf8re et komplet 3D-spil i en \xe5ben verden p\xe5 en 1 $-mikrocontroller. Motoren indeholder en lille by og udkantsomr\xe5der med skydebare zombier, og der findes Blender-tutorials til at skabe spilverdener. Motorsimuleringen indeholder i \xf8jeblikket 50 NPC'er og 50 zombier p\xe5 samme tid, med rendering optimeret med afstand og view frustum culling."]}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35589172",children:"Discussion Service"}),".\nEn ny 3D-spilmotor kaldet Pico3D er blevet udviklet til RP2040-mikrocontrolleren med en 120x120px-sk\xe6rm, og den mangler nok hukommelse og video-RAM, men har en forenet API. Hackere er begejstrede for kreative m\xe5der at bruge Pico/RP2040 p\xe5, og den unikke anvendelse af RAM-chips i billedbufferen g\xf8r, at denne artikel skiller sig ud p\xe5 det tekniske site."]}),"\n",(0,n.jsx)(r.h2,{id:"wayback-self-hosted-arkiveringstjeneste-integreret-med-internet-archive",children:"Wayback: Self-hosted arkiveringstjeneste integreret med Internet Archive"}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.a,{href:"https://github.com/wabarc/wayback",children:"Original"}),".\nWayback er et selvhostet arkiveringsv\xe6rkt\xf8j, der har til form\xe5l at tage \xf8jebliksbilleder af websider i tidskapsler. Det er gratis, open source, cross-platform og giver mulighed for lettere integration med forskellige platforme, herunder Internet Archive, archive.today, IPFS og Telegraph. Det giver ogs\xe5 flere installationsmuligheder, bl.a. via GitHub, Snapcraft, APT, RPM og Homebrew."]}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35586845",children:"Discussion Service"}),'.\nDen selvhostede arkiveringstjeneste Wabarc tager snapshots af websider i "tidskapsler" og gemmer filer til offline brug; Discussion Service-brugere kritiserer dog den uklare README og manglen p\xe5 dokumentation. Andre lignende projekter omfatter ArchiveBox, Shiori, DiskerNet og SingleFile; HTTrack Website Copier anbefales til at downloade et helt websted lokalt, mens Browsertrix/Brozzler crawler med headless browsere for n\xf8jagtighed. En Discussion Service-bruger anbefaler The Old Net til browsing af gamle/moderne browsere uden JS, og den repo, der linkes til, har brug for mere klarhed om delbarhed og etablerede arkiveringsstandarder.']}),"\n",(0,n.jsx)(r.h2,{id:"det-hurtigste-matematiske-s\xe6tningsbibliotek-til-nettet",children:"Det hurtigste matematiske s\xe6tningsbibliotek til nettet"}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.a,{href:"https://katex.org/",children:"Original"}),".\nKaTeX er et hurtigt matematisk s\xe6tningsbibliotek til internettet, der tilbyder layout i trykkvalitet baseret p\xe5 Donald Knuths TeX, som ikke har nogen afh\xe6ngigheder, og som nemt kan bundles med webstedsressourcer til server-side rendering ved hj\xe6lp af Node.js. Dets enkle API gengiver effektivt matematiske udtryk, selv p\xe5 sider med flere udtryk, uden nogen browser- eller milj\xf8begr\xe6nsning, og det er open source under MIT-licensen."]}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35588985",children:"Discussion Service"}),".\nKaTeX, det hurtigste bibliotek til matematisk satsning p\xe5 nettet, mangler underst\xf8ttelse af diagrammer, hvilket g\xf8r det uegnet for nogle matematikere, mens MathJax og AsciiMath begge har lignende projekter. Der er blevet delt et sammenligningswebsted, og Hacker News-brugere diskuterer ydeevne og praktiske muligheder for at tilpasse markup til forskellige sammenh\xe6nge."]}),"\n",(0,n.jsx)(r.h2,{id:"algebra-for-none-mislykkes-i-san-francisco",children:"'Algebra for none' mislykkes i San Francisco"}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.a,{href:"https://www.joannejacobs.com/post/algebra-for-none-fails-in-san-francisco",children:"Original"}),'.\nSan Francisco Unified School District\'s "Algebra for none"-politik har if\xf8lge en unders\xf8gelse foretaget af Stanford-professorer ikke form\xe5et at forbedre sorte og latinamerikanske elevers resultater i matematik p\xe5 h\xf8jt niveau, hvilket har resulteret i en voksende pr\xe6stationskl\xf8ft. Beslutningen om at uds\xe6tte algebra til niende klasse og placere elever med ringe og h\xf8je resultater i de samme klasser hjalp ikke de elever med ringe resultater og gjorde det sv\xe6rere for elever med h\xf8je resultater at klare sig. Familier, der har r\xe5d, har vendt sig mod onlinekurser eller privatskoler. En gruppe for\xe6ldre har anlagt sag mod distriktet og h\xe6vder, at det er i strid med statens lov om lige adgang til avanceret matematik.']}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35595026",children:"Discussion Service"}),".\nSan Franciscos politik med at uds\xe6tte algebra til 9. klasse og placere elever med lave, gennemsnitlige og h\xf8je resultater i de samme klasser er blevet kritiseret, idet nogle foresl\xe5r, at grundl\xe6ggende matematiske begreber b\xf8r l\xe6res tidligere. Nogle Discussion Service-brugere foresl\xe5r, at man tilskynder til akademisk og ekstracurricul\xe6r succes ved at knytte den til \xf8konomisk bel\xf8nning, mens andre h\xe6vder, at det ville v\xe6re en bedre l\xf8sning at subsidiere h\xf8jere uddannelse gennem kreditsystemer, s\xe5 man senere kan betale for college. Der er debat om nytten af traditionel matematikundervisning og effektiviteten af at \xf8ge midlerne for at reducere klassest\xf8rrelserne, idet nogle brugere foresl\xe5r at undervise i matematik gennem tekniske problemer og fordelene ved onlineundervisning."]}),"\n",(0,n.jsx)(r.h2,{id:"fsf-sm\xe6kker-google-over-at-droppe-jpeg-xl-i-chrome",children:"FSF sm\xe6kker Google over at droppe JPEG-XL i Chrome"}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.a,{href:"https://www.phoronix.com/news/FSF-Slams-Google-JPEG-XL",children:"Original"}),'.\nFree Software Foundation kritiserer Googles beslutning om at droppe JPEG-XL-underst\xf8ttelsen i Chrome og fremh\xe6ver behovet for valg af browser og frie medieformater. P\xe5 trods af samfundets opr\xf8r gik Googles ingeni\xf8rer alligevel videre med beslutningen, som stadig er et af de mest "stjernede" problemer i Chromium-projektets historie. Brugerne har vist stor opbakning til JPEG-XL, men Googles fokus p\xe5 kontrol frem for frihed synes at sejre.']}),"\n",(0,n.jsxs)(r.p,{children:[(0,n.jsx)(r.a,{href:"http://news.ycombinator.com/item?id=35589179",children:"Discussion Service"}),".\nGoogle m\xf8der kritik fra Free Software Foundation for at have indstillet underst\xf8ttelsen af JPEG-XL i Chrome p\xe5 trods af, at det er blevet indf\xf8rt af store billedredigeringsprogrammer. Nogle brugere h\xe6vder, at \xe6ldre formater som PNG og JPEG er tilstr\xe6kkelige, mens andre foretr\xe6kker codecs som AVIF til video. Debatten drejer sig om levedygtigheden og vedtagelsen af nye billedformater i \xf8kosystemet, hvor industriens st\xf8tte til og interesse for JPEG-XL er noteret, men vedtagelsen er afh\xe6ngig af, at alle st\xf8rre browsere underst\xf8tter det."]})]})}function m(e={}){const{wrapper:r}={...(0,s.R)(),...e.components};return r?(0,n.jsx)(r,{...e,children:(0,n.jsx)(g,{...e})}):g(e)}}}]);